-- =============================================================================
-- 0030_varalakshmi_from_the_book.sql
--
-- GENERATED by scripts/build-varalakshmi-book.mjs. Do not hand-edit.
--
-- Varalakshmi was built entirely on StotraNidhi, one web source in the Telugu
-- tradition. Checked now against a printed Smartha source -- Sampradaya Vratha
-- Pooja Vidhi (Giri), pp.110-137.
--
-- Adds four upacharas the book has and the app lacked, and replaces two things
-- that are defects rather than differences of tradition:
--
--   * Ksheera Arghyam recited the wrong verse. Its archana row was a verbatim
--     copy of step 12 -- shuddhOdakam, "pure water" -- in the one step whose
--     offering is milk. The book gives gOkSHeerENa yutam, which belongs here.
--   * Ashtottara 106 read brahmaa-viSHNu-. A dvandva does not lengthen its
--     first member. The book has brahma-viSHNu-.
--
-- It removes nothing, and deliberately leaves the fifteen-limb Anga Pooja
-- alone: the book gives twenty-four different limbs, which is a second
-- tradition rather than a correction. See the review sheet.
--
-- Idempotent: every append is guarded on the text it would add.
-- =============================================================================

begin;

-- --- 1. upacharas the book has that the app lacked ---------------------------
-- Madhuparkam is its own upachara in the shodashopachara sequence, between
-- aachamaneeyam and the panchamrita snanam (p.118).
update public.pooja_steps set
       mantra_sanskrit = mantra_sanskrit || chr(10) || 'महालक्ष्मि महादेवि मध्वाज्य दधि संयुतम् ।
मधुपर्कं गृहाणेदं मधुसूदनवल्लभे ॥
श्री वरलक्ष्म्यै नमः मधुपर्कं समर्पयामि ॥',
       mantra_tamil    = mantra_tamil    || chr(10) || 'மஹாலக்ஷ்மி மஹாதேவி மத்வாஜ்ய ததி ஸம்யுதம் ।
மதுபர்கம் க்ருஹாணேதம் மதுஸூதநவல்லபே ॥
ஶ்ரீ வரலக்ஷ்ம்யை நம꞉ மதுபர்கம் ஸமர்பயாமி ॥',
       mantra_translit = mantra_translit || chr(10) || 'mahālakṣmi mahādevi madhvājya dadhi saṃyutam ।
madhuparkaṃ gṛhāṇedaṃ madhusūdanavallabhe ॥
śrī varalakṣmyai namaḥ madhuparkaṃ samarpayāmi ॥',
       updated_at      = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Padyam, Arghyam & Achamaniyam'
   and mantra_sanskrit not like '%मधुपर्कं%';

-- Turmeric over the sandal paste, given as its own line (p.120).
update public.pooja_steps set
       mantra_sanskrit = mantra_sanskrit || chr(10) || 'गन्धोपरि हरिद्राचूर्णं समर्पयामि ॥',
       mantra_tamil    = mantra_tamil    || chr(10) || 'கந்தோபரி ஹரித்ராசூர்ணம் ஸமர்பயாமி ॥',
       mantra_translit = mantra_translit || chr(10) || 'gandhopari haridrācūrṇaṃ samarpayāmi ॥',
       updated_at      = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Gandham, Akshatai & Pushpam'
   and mantra_sanskrit not like '%हरिद्राचूर्णं%';

-- The rajopachara: parasol, fan, dance, song, instrument (p.133).
update public.pooja_steps set
       mantra_sanskrit = mantra_sanskrit || chr(10) || 'छत्र–चामर–नृत्त–गीत–वाद्य इत्यादि
समस्तोपचार–शक्त्युपचार–देवोपचारान् समर्पयामि ॥',
       mantra_tamil    = mantra_tamil    || chr(10) || 'சத்ர–சாமர–ந்ருத்த–கீத–வாத்ய இத்யாதி
ஸமஸ்தோபசார–ஶக்த்யுபசார–தேவோபசாராந் ஸமர்பயாமி ॥',
       mantra_translit = mantra_translit || chr(10) || 'chatra–cāmara–nṛtta–gīta–vādya ityādi
samastopacāra–śaktyupacāra–devopacārān samarpayāmi ॥',
       updated_at      = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Namaskaram & Varalakshmi Prarthana'
   and mantra_sanskrit not like '%छत्र%';

-- kaayEna vaachaa and the brahmarpanam that close the rite (p.136).
update public.pooja_steps set
       mantra_sanskrit = mantra_sanskrit || chr(10) || 'कायेन वाचा मनसेन्द्रियैर्वा बुद्ध्यात्मना वा प्रकृतेः स्वभावात् ।
करोमि यद्यत् सकलं परस्मै नारायणायेति समर्पयामि ॥
ॐ तत् सत् ब्रह्मार्पणमस्तु ॥',
       mantra_tamil    = mantra_tamil    || chr(10) || 'காயேந வாசா மநஸேந்த்ரியைர்வா புத்த்யாத்மநா வா ப்ரக்ருதே꞉ ஸ்வபாவாத் ।
கரோமி யத்யத் ஸகலம் பரஸ்மை நாராயணாயேதி ஸமர்பயாமி ॥
ஓம் தத் ஸத் ப்ரஹ்மார்பணமஸ்து ॥',
       mantra_translit = mantra_translit || chr(10) || 'kāyena vācā manasendriyairvā buddhyātmanā vā prakṛteḥ svabhāvāt ।
karomi yadyat sakalaṃ parasmai nārāyaṇāyeti samarpayāmi ॥
oṃ tat sat brahmārpaṇamastu ॥',
       updated_at      = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Kshama Prarthana & Conclusion'
   and mantra_sanskrit not like '%ब्रह्मार्पणमस्तु%';

-- --- 2. the ksheera arghyam gets its own verse -------------------------------
-- The resolve, said once before the pouring, goes on the step itself; the
-- verse and its refrain go on the archana row the screen lets you tick off.
update public.pooja_steps set
       mantra_sanskrit = 'ममोपात्त समस्त दुरितक्षयद्वारा श्री परमेश्वर प्रीत्यर्थं,
श्री वरलक्ष्मी पूजाफल संपूर्णता सिद्ध्यर्थं
क्षीरार्घ्यं प्रदानं करिष्ये ॥',
       mantra_tamil    = 'மமோபாத்த ஸமஸ்த துரிதக்ஷயத்வாரா ஶ்ரீ பரமேஶ்வர ப்ரீத்யர்தம்,
ஶ்ரீ வரலக்ஷ்மீ பூஜாபல ஸம்பூர்ணதா ஸித்த்யர்தம்
க்ஷீரார்க்யம் ப்ரதாநம் கரிஷ்யே ॥',
       mantra_translit = 'mamopātta samasta duritakṣayadvārā śrī parameśvara prītyarthaṃ,
śrī varalakṣmī pūjāphala saṃpūrṇatā siddhyarthaṃ
kṣīrārghyaṃ pradānaṃ kariṣye ॥',
       source_ref      = 'Sampradaya Vratha Pooja Vidhi (Giri), pp.135-136',
       updated_at      = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Ksheera Arghyam';

update public.archana_items set
       invoked_name_deva     = 'गोक्षीरेणयुतं देवि गन्धपुष्पसमन्वितम् ।
अर्घ्यं गृहाण वरदे वरलक्ष्मि नमोऽस्तु ते ॥',
       invoked_name_ta       = 'கோக்ஷீரேணயுதம் தேவி கந்தபுஷ்பஸமந்விதம் ।
அர்க்யம் க்ருஹாண வரதே வரலக்ஷ்மி நமோஸ்து தே ॥',
       invoked_name_translit = 'gokṣīreṇayutaṃ devi gandhapuṣpasamanvitam ।
arghyaṃ gṛhāṇa varade varalakṣmi namo''stu te ॥',
       offering_deva         = 'श्री वरलक्ष्म्यै नमः इदमर्घ्यम्, इदमर्घ्यम्, इदमर्घ्यम् ॥',
       offering_ta           = 'ஶ்ரீ வரலக்ஷ்ம்யை நம꞉ இதமர்க்யம், இதமர்க்யம், இதமர்க்யம் ॥',
       offering_en           = 'Pour the milk arghyam three times'
 where pooja_step_id = (select id from public.pooja_steps
