-- --- 3. one ungrammatical name -----------------------------------------------
update public.namavali_items set
       name_deva     = 'ॐ ब्रह्मविष्णुशिवात्मिकायै नमः',
       name_ta       = 'ஓம் ப்ரஹ்மவிஷ்ணுஶிவாத்மிகாயை நம꞉',
       name_translit = 'oṃ brahmaviṣṇuśivātmikāyai namaḥ'
 where namavali_id = 'lakshmi_ashtottara_108' and seq = 106
   and name_deva like '%ब्रह्माविष्णु%';

-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  -- The four additions each landed exactly once.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham'
     and step_title_en = 'Padyam, Arghyam & Achamaniyam'
     and mantra_sanskrit like '%मधुपर्कं%';
  if n <> 1 then raise exception 'madhuparkam did not land'; end if;

  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham'
     and step_title_en = 'Kshama Prarthana & Conclusion'
     and mantra_sanskrit like '%ब्रह्मार्पणमस्तु%';
  if n <> 1 then raise exception 'the brahmarpanam did not land'; end if;

  -- The milk arghyam no longer recites the water verse.
  select count(*) into n from public.archana_items a
   join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'varalakshmi_vratham' and s.step_title_en = 'Ksheera Arghyam'
     and a.invoked_name_deva like '%शुद्धोदक%';
  if n > 0 then raise exception 'ksheera arghyam still says shuddhodaka'; end if;

  select count(*) into n from public.archana_items a
   join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'varalakshmi_vratham' and s.step_title_en = 'Ksheera Arghyam'
     and a.invoked_name_deva like '%गोक्षीर%';
  if n <> 1 then raise exception 'ksheera arghyam has no milk verse'; end if;

  -- Name 106 is grammatical.
  select count(*) into n from public.namavali_items
   where namavali_id = 'lakshmi_ashtottara_108' and name_deva like '%ब्रह्माविष्णु%';
  if n > 0 then raise exception 'name 106 still has the long aa'; end if;

  -- Nothing was added or removed structurally.
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham';
  if n <> 29 then raise exception 'varalakshmi has % steps, expected 29', n; end if;

  -- The anga pooja was left alone, at its fifteen limbs.
  select count(*) into n from public.archana_items a
   join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'varalakshmi_vratham' and s.step_title_en = 'Anga Pooja';
  if n <> 15 then raise exception 'anga pooja has % rows, expected 15', n; end if;

  -- Every step that has Devanagari has the other two scripts too.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham'
     and coalesce(trim(mantra_sanskrit), '') <> ''
     and (mantra_tamil is null or mantra_translit is null);
  if n > 0 then raise exception '% steps are missing a script', n; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
